const body = $json.body || $json;

// sessionId vem do front (UUID em localStorage)
const sessionId =
  body.sessionId ||
  body.conversationId ||
  body.visitorId ||
  `web_${$execution.id}`;

// lead_key = sessionId (estavel cross-mensagem do mesmo visitante)
const leadKey = sessionId;

const message =
  body.message ||
  body.text ||
  body.content ||
  '';

return [
  {
    json: {
      lead_key: String(leadKey).trim(),
      message: String(message || '').trim(),
      session_id: String(sessionId).trim(),
      source: 'site',
      timestamp: body.timestamp || new Date().toISOString(),
      name: body.name || '',
      email: body.email || '',
      phone: body.phone || ''
    }
  }
];

let row = $json;
if (Array.isArray(row)) row = row[0] || {};
if (row.lead_data) row = row.lead_data;

return [
  {
    json: {
      lead_key: $("Normalize Data").item.json.lead_key,
      message: $("Normalize Data").item.json.message,
      timestamp: $("Normalize Data").item.json.timestamp,
      lead_data: row,
      historico: []
    }
  }
];

const leadData = $json.lead_data || {};
let historico = leadData.historico || [];

if (typeof historico === "string") {
  try {
    historico = JSON.parse(historico);
  } catch (e) {
    historico = [];
  }
}

if (!Array.isArray(historico)) {
  historico = [];
}

return [
  {
    json: {
      lead_key: $("Normalize Data").item.json.lead_key,
      message: $("Normalize Data").item.json.message,
      timestamp: $("Normalize Data").item.json.timestamp,
      lead_data: leadData,
      historico
    }
  }
];

const historico = Array.isArray($json.historico) ? $json.historico : [];

const historico_updated = historico.concat([
  {
    role: "user",
    content: $json.message,
    timestamp: $json.timestamp
  }
]);

return [
  {
    json: {
      ...$json,
      historico_updated
    }
  }
];

function normalizeReplies(parsed) {
  // Preferência: array novo "respostas_cliente". Fallback: string antiga "resposta_cliente".
  let arr = [];
  if (Array.isArray(parsed.respostas_cliente)) {
    arr = parsed.respostas_cliente;
  } else if (typeof parsed.respostas_cliente === "string" && parsed.respostas_cliente.trim()) {
    arr = [parsed.respostas_cliente];
  } else if (typeof parsed.resposta_cliente === "string" && parsed.resposta_cliente.trim()) {
    // Retro-compat: se a IA voltou pro formato antigo, divide em \n\n
    arr = parsed.resposta_cliente.split(/\n\s*\n/);
  }
  // Limpa, filtra vazias, trunca pra max 5 (segurança contra IA enlouquecer)
  return arr.map(s => String(s || "").trim()).filter(Boolean).slice(0, 5);
}

try {
  const input = $input.item.json;

  let aiResponse =
    input.choices?.[0]?.message?.content ??
    input.output?.[0]?.content?.[0]?.text ??
    input.message?.content ??
    input.text ??
    input.response ??
    input.output ??
    "";

  let parsed;

  if (typeof aiResponse === "object" && !Array.isArray(aiResponse)) {
    parsed = aiResponse;
  } else if (typeof aiResponse === "string") {
    const jsonMatch = aiResponse.match(/```(?:json)?\s*([\s\S]*?)```/);
    const jsonStr = jsonMatch ? jsonMatch[1].trim() : aiResponse.trim();
    parsed = JSON.parse(jsonStr);
  } else {
    throw new Error("Formato inválido retornado pela IA");
  }

  const respostas = normalizeReplies(parsed);
  if (respostas.length === 0) {
    throw new Error("Missing respostas_cliente in AI response");
  }

  return [
    {
      json: {
        // Novo contrato
        respostas_cliente: respostas,
        // Retro-compat: nodes legados (Notion, email) ainda leem string única
        resposta_cliente: respostas.join("\n\n"),
        dados_coletados: parsed.dados_coletados || {},
        briefing_completo: Boolean(parsed.briefing_completo),
        resumo_interno: parsed.resumo_interno || "",
        prioridade: ["baixa", "media", "alta"].includes(parsed.prioridade) ? parsed.prioridade : "baixa",
        status: parsed.status || (parsed.briefing_completo ? "qualificado" : "em_atendimento"),
        lead_key: $("Append User Message to History").item.json.lead_key,
        lead_data: $("Append User Message to History").item.json.lead_data,
        historico_updated: $("Append User Message to History").item.json.historico_updated,
        timestamp: $("Append User Message to History").item.json.timestamp
      }
    }
  ];
} catch (error) {
  const fallbackMsg = "Desculpe, tive um problema técnico ao processar sua mensagem. Pode tentar novamente em alguns instantes?";
  return [
    {
      json: {
        respostas_cliente: [fallbackMsg],
        resposta_cliente: fallbackMsg,
        dados_coletados: {},
        briefing_completo: false,
        resumo_interno: "Erro no processamento da IA: " + error.message,
        prioridade: "media",
        status: "em_atendimento",
        lead_key: $("Append User Message to History").item.json.lead_key,
        lead_data: $("Append User Message to History").item.json.lead_data,
        historico_updated: $("Append User Message to History").item.json.historico_updated || [],
        timestamp: $("Append User Message to History").item.json.timestamp,
        error: error.message
      }
    }
  ];
}

const historico = Array.isArray($json.historico_updated)
  ? $json.historico_updated
  : [];

const historico_final = historico.concat([
  {
    role: "assistant",
    content: $json.resposta_cliente,
    timestamp: new Date().toISOString()
  }
]);

return [
  {
    json: {
      ...$json,
      historico_final,
      ai_response: {
        respostas_cliente: Array.isArray($json.respostas_cliente) ? $json.respostas_cliente : [$json.resposta_cliente],
        resposta_cliente: $json.resposta_cliente,
        dados_coletados: $json.dados_coletados,
        briefing_completo: $json.briefing_completo,
        resumo_interno: $json.resumo_interno,
        prioridade: $json.prioridade,
        status: $json.status
      }
    }
  }
];

