const lead = $("DB - Update Lead").item.json;
const notion = $json || {};

const resumo = `🚀 Novo lead qualificado - HSB

Nome: ${lead.nome || "Não informado"}
Empresa: ${lead.empresa || "Não informada"}
Contato: ${lead.email || ""} ${lead.phone || ""}
Serviço: ${lead.servico || "Não definido"}
Objetivo: ${lead.objetivo || "Não informado"}
Urgência: ${lead.urgencia || "Não informada"}
Prazo: ${lead.prazo || "Não informado"}
Prioridade: ${lead.prioridade || "baixa"}

Resumo:
${lead.resumo_interno || "Sem resumo interno gerado."}

Recomendação:
Entrar em contato com abordagem consultiva, confirmar necessidade, escopo, orçamento disponível e prazo desejado.

Ação necessária:
Preparar orçamento e prazo personalizado.

Supabase Lead ID:
${lead.id || ""}

Notion:
${notion.url || ""}`;

return [
  {
    json: {
      ...lead,
      notion_page_id: notion.id || "",
      notion_url: notion.url || "",
      email_subject: `Novo lead qualificado - HSB: ${lead.empresa || lead.nome || lead.lead_key}`,
      email_body: resumo
    }
  }
];

const ai = $json.ai_response || $json;
const dados = ai.dados_coletados || {};

let step = null;

if (ai.briefing_completo === true) {
  step = 'contact_data_complete';
} else if (
  (dados.email && String(dados.email).trim()) ||
  (dados.phone && String(dados.phone).trim()) ||
  (dados.nome && String(dados.nome).trim())
) {
  step = 'contact_data_collecting';
} else if (dados.servico && String(dados.servico).trim()) {
  step = 'service_identified';
}

return [
  {
    json: {
      ...$json,
      step
    }
  }
];
